export type Line = { sku: string; unitPriceCents: number; quantity: number };
export type Quote = { region: string; subtotalCents: number; taxCents: number; totalCents: number };

export function subtotal(lines: Line[]): number {
  return lines.reduce((sum, l) => sum + l.unitPriceCents * l.quantity, 0);
}

/** Price a cart for a region, given that region's fractional tax rate (0.19 = 19%). */
export function quote(lines: Line[], region: string, taxRate: number): Quote {
  const subtotalCents = subtotal(lines);
  const taxCents = Math.round(subtotalCents * taxRate);
  return { region, subtotalCents, taxCents, totalCents: subtotalCents + taxCents };
}
EOF
cat > src/pricing/application/quote-service.ts <<'EOF'
import { quote, type Line, type Quote } from "../domain/quote.ts";
import { getTaxRate } from "../integration/tax-rates.ts";

/** Use case: produce a customer-facing quote for a cart in a region. */
export function quoteForCart(lines: Line[], region: string): Quote {
  return quote(lines, region, getTaxRate(region));
}
EOF
